int tipsy_pack_jargs(const char *sig, va_list ap, jvalue *out, int max)
{
	const char *p;
	int n = 0;

	if (sig == NULL || out == NULL || max <= 0) {
		return 0;
	}
	p = sig;
	if (*p == '(') {
		p++;
	}
	while (*p && *p != ')' && n < max) {
		switch (*p) {
		case 'Z':
		case 'B':
		case 'C':
		case 'S':
		case 'I':
			out[n++].i = va_arg(ap, int);
			p++;
			break;
		case 'J':
			out[n++].j = va_arg(ap, int64_t);
			p++;
			break;
		case 'F':
			out[n++].f = (float)va_arg(ap, double);
			p++;
			break;
		case 'D':
			out[n++].d = va_arg(ap, double);
			p++;
			break;
		case 'L':
			out[n++].l = va_arg(ap, jobject);
			while (*p && *p != ';') {
				p++;
			}
			if (*p == ';') {
				p++;
			}
			break;
		case '[':
			out[n++].l = va_arg(ap, jobject);
			p++;
			while (*p == '[') {
				p++;
			}
			if (*p == 'L') {
				while (*p && *p != ';') {
					p++;
				}
				if (*p == ';') {
					p++;
				}
			} else if (*p) {
				p++;
			}
			break;
		default:
			p++;
			break;
		}
	}
	return n;
}

static const char *method_sig(jmethodID mid)
{
	TipsyMethod *m = (TipsyMethod *)mid;
	if (m != NULL && m->magic == TIPSY_METHOD_MAGIC && m->sig != NULL) {
		return m->sig;
	}
	return "()V";
}

