static jvalue call_a(JNIEnv *env, jobject obj, jclass clazz, jmethodID mid, const jvalue *args, jint is_static, jint kind)
{
	jvalue out;
	memset(&out, 0, sizeof out);
	TIPSY_JNI_STUTTER_DIAG_RECORD(is_static ? 1 : (clazz != NULL ? 2 : 0));
	GoJNI_CallA(env, obj, clazz, mid, args, is_static, kind, &out);
	return out;
}

static jvalue call_v(JNIEnv *env, jobject obj, jclass clazz, jmethodID mid, va_list ap, jint is_static, jint kind)
{
	jvalue packed[16];
	memset(packed, 0, sizeof packed);
	tipsy_pack_jargs(method_sig(mid), ap, packed, 16);
	return call_a(env, obj, clazz, mid, packed, is_static, kind);
}

#define CALL_VARARGS(ret, name, kind, field, is_static)                                                          \
	static ret JNICALL t_##name(JNIEnv *env, jobject obj, jmethodID methodID, ...)                           \
	{                                                                                                        \
		va_list ap;                                                                                      \
		jvalue v;                                                                                        \
		va_start(ap, methodID);                                                                          \
		v = call_v(env, obj, NULL, methodID, ap, is_static, kind);                                       \
		va_end(ap);                                                                                      \
		return v.field;                                                                                  \
	}

#define CALL_V(ret, name, kind, field, is_static)                                                                \
	static ret JNICALL t_##name(JNIEnv *env, jobject obj, jmethodID methodID, va_list args)                  \
	{                                                                                                        \
		jvalue v = call_v(env, obj, NULL, methodID, args, is_static, kind);                              \
		return v.field;                                                                                  \
	}

#define CALL_A(ret, name, kind, field, is_static)                                                                \
	static ret JNICALL t_##name(JNIEnv *env, jobject obj, jmethodID methodID, const jvalue *args)             \
	{                                                                                                        \
		jvalue v = call_a(env, obj, NULL, methodID, args, is_static, kind);                              \
		return v.field;                                                                                  \
	}

